// 1. Capturamos la trama hexadecimal del primer paquete de SatNOGS
const hexFrame = $input.first().json.results[0].frame;

// 2. Funciones de ayuda para extraer Bytes (Cada byte son 2 caracteres)
function extraerByte(hex, posicion) {
    // Corta 2 caracteres en la posición indicada y los pasa de Hex a Decimal
    const pedazoHex = hex.substring(posicion * 2, (posicion * 2) + 2);
    return parseInt(pedazoHex, 16);
}

function extraerDosBytes(hex, posicion) {
    // Corta 4 caracteres para datos más grandes (como voltaje)
    const pedazoHex = hex.substring(posicion * 2, (posicion * 2) + 4);
    return parseInt(pedazoHex, 16);
}

// 3. DECODIFICACIÓN (Ajustada para la trama del SALSAT en la demo)
// En la trama real, el Byte 8 (A8 en hex) tiene el valor decimal 168
let byteTemperatura = extraerByte(hexFrame, 8); 

// Los Bytes 10 y 11 (325D en hex) tienen el valor decimal 12893
let byteVoltaje = extraerDosBytes(hexFrame, 10); 

// 4. Aplicamos las fórmulas matemáticas para simular la realidad
// Convertimos el 168 a unos 28°C realistas (ej: Valor - 140)
let temperaturaFinal = byteTemperatura - 140; 

// Convertimos el 12893 a un voltaje de batería realista de 7.5V (ej: Valor / 1700)
let voltajeFinal = (byteVoltaje / 1700).toFixed(2); // toFixed(2) deja solo 2 decimales

// 5. Devolvemos un JSON limpio
return {
    temperatura_obc: temperaturaFinal,
    voltaje_bateria: Number(voltajeFinal), // Lo convertimos de nuevo a número por las dudas
    trama_original: hexFrame
};;
